const { execSync } = require('child_process');
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
const backups = `${prj}/IMPAR_OS/backups`;
const ts = new Date().toISOString().replace(/[:.]/g,'-').substring(0,19);
const out = {};
try {
  execSync(`cp "${prj}/IMPAR_OS/database/impar.db" "${backups}/impar-${ts}.db" 2>/dev/null`, {timeout:10000});
  out.db = `impar-${ts}.db`;
} catch(e) { out.db_error = e.message.substring(0,100); }
try {
  execSync(`cp "${prj}/IMPAR_OS/registry/registry.json" "${backups}/registry-${ts}.json" 2>/dev/null`, {timeout:5000});
  out.registry = `registry-${ts}.json`;
} catch(e) { out.registry_error = e.message.substring(0,100); }
try {
  const old = execSync(`ls "${backups}" | sort | head -n -14 2>/dev/null`, {timeout:5000}).toString().trim().split('\n').filter(Boolean);
  old.forEach(f => { try { execSync(`rm "${backups}/${f}"`, {timeout:3000}); } catch(e) {} });
  out.cleaned = old.length;
} catch(e) { out.clean_error = e.message.substring(0,100); }
return [{ json: { status: 'ok', ai_used: false, timestamp: new Date().toISOString(), backup: out } }];
